#!/usr/bin/env python3
"""Vendor the app's web fonts locally so Sage Stage is fully offline / no CDN.

Downloads the woff2 files Google Fonts serves for the UI ("chrome") families,
plus OpenDyslexic (from Fontsource) as a bundled dyslexia option, and writes a
self-contained fonts.css next to them. Keeps only the `latin` + `latin-ext`
subsets (English + European accented names); other scripts fall back to system
fonts, exactly as with partial coverage.

All fonts here are OFL (SIL Open Font License) — safe to redistribute. Paid
school fonts (cursive handwriting schemes, Dyslexie, …) are NEVER bundled; those
are referenced from the machine's own install via the in-app font picker.

Re-run after changing weights:  python3 vendor/fonts/fetch-fonts.py
"""
import re, subprocess, sys, pathlib

HERE = pathlib.Path(__file__).resolve().parent          # vendor/fonts
UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
      "(KHTML, like Gecko) Chrome/120.0 Safari/537.36")
KEEP_SUBSETS = {"latin", "latin-ext"}

GOOGLE_CSS = ("https://fonts.googleapis.com/css2?"
    "family=Atkinson+Hyperlegible:wght@400;700"
    "&family=Graduate"
    "&family=Lexend:wght@400;600;700"
    "&family=Lilita+One"
    "&family=Mali:wght@400;600"
    "&family=Pacifico"
    "&family=Poppins:wght@500;600;700"
    "&family=Quicksand:wght@500;600;700"
    "&display=swap")

# OpenDyslexic via Fontsource (OFL). name, weight, url
OPEN_DYSLEXIC = [
    ("OpenDyslexic", 400, "https://cdn.jsdelivr.net/fontsource/fonts/opendyslexic@latest/latin-400-normal.woff2"),
    ("OpenDyslexic", 700, "https://cdn.jsdelivr.net/fontsource/fonts/opendyslexic@latest/latin-700-normal.woff2"),
]

def curl(url, out=None):
    cmd = ["curl", "-sSfL", "-A", UA, "--max-time", "60", url]
    if out:
        cmd += ["-o", str(out)]
        subprocess.run(cmd, check=True)
        return None
    return subprocess.run(cmd, check=True, capture_output=True).stdout.decode("utf-8", "replace")

def slug(name):
    return re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")

def parse_google(css):
    """Yield (family, weight, subset, url, unicode_range) per @font-face."""
    subset = None
    for block in re.split(r"(?=/\*|@font-face)", css):
        m = re.match(r"/\*\s*([\w-]+)\s*\*/", block.strip())
        if m:
            subset = m.group(1)
            continue
        if "@font-face" not in block:
            continue
        fam = re.search(r"font-family:\s*'([^']+)'", block)
        wght = re.search(r"font-weight:\s*(\d+)", block)
        url = re.search(r"src:\s*url\(([^)]+)\)", block)
        rng = re.search(r"unicode-range:\s*([^;]+);", block)
        if fam and wght and url:
            yield fam.group(1), int(wght.group(1)), subset, url.group(1), (rng.group(1).strip() if rng else None)

def face(family, weight, filename, unicode_range):
    ur = f"\n  unicode-range: {unicode_range};" if unicode_range else ""
    return (f"@font-face {{\n"
            f"  font-family: '{family}';\n"
            f"  font-style: normal;\n"
            f"  font-weight: {weight};\n"
            f"  font-display: swap;\n"
            f"  src: url({filename}) format('woff2');{ur}\n"
            f"}}\n")

def main():
    print("Fetching Google Fonts CSS…")
    css = curl(GOOGLE_CSS)
    faces, downloaded = [], 0
    for family, weight, subset, url, rng in parse_google(css):
        if subset not in KEEP_SUBSETS:
            continue
        sub_tag = subset.replace("-", "")           # latin / latinext
        filename = f"{slug(family)}-{weight}-{sub_tag}.woff2"
        curl(url, HERE / filename)
        downloaded += 1
        faces.append(face(family, weight, filename, rng))
        print(f"  ✓ {filename}")

    print("Fetching OpenDyslexic (Fontsource, OFL)…")
    for family, weight, url in OPEN_DYSLEXIC:
        filename = f"{slug(family)}-{weight}-latin.woff2"
        curl(url, HERE / filename)
        downloaded += 1
        faces.append(face(family, weight, filename, None))
        print(f"  ✓ {filename}")

    header = ("/* Generated by fetch-fonts.py — do not edit by hand.\n"
              "   Self-hosted OFL fonts so Sage Stage needs no font CDN (100% local).\n"
              "   Regenerate: python3 vendor/fonts/fetch-fonts.py */\n\n")
    (HERE / "fonts.css").write_text(header + "".join(faces))
    print(f"\nDone: {downloaded} woff2 files + fonts.css")

if __name__ == "__main__":
    sys.exit(main())
